/**
 * db.js — PostgreSQL connection pool module
 *
 * Loads DATABASE_URL from .env.test (or the active .env file) via dotenv,
 * then creates and exports a pg Pool instance together with a healthCheck()
 * helper. The actual credential value is never logged, stored, or transmitted;
 * only the environment-variable *name* appears in this source file.
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1.  Load environment variables
//     dotenv.config() is a no-op when the variable is already set, so this is
//     safe to call in every environment without overwriting CI/CD injections.
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');

const envFile = path.resolve(__dirname, '.env.test');
const dotenvResult = dotenv.config({ path: envFile });

if (dotenvResult.error) {
  // Warn but do not crash — the variable may already be present in the process
  // environment (e.g. injected by a secrets manager in production).
  console.warn(
    `[db] Warning: could not load ${envFile}: ${dotenvResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2.  Validate that DATABASE_URL is actually present before creating the pool
// ---------------------------------------------------------------------------
if (!process.env.DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not set. ' +
      'Add it to .env.test or inject it through the process environment.'
  );
}

// ---------------------------------------------------------------------------
// 3.  Pool configuration
//
//     pg.Pool accepts either a `connectionString` or individual host/port/…
//     fields.  Using the connection string keeps the module decoupled from the
//     exact shape of the URL.
//
//     Sensible defaults are chosen for a web-service workload; adjust them to
//     match your database server's max_connections and expected concurrency.
// ---------------------------------------------------------------------------
const POOL_CONFIG = {
  connectionString: process.env.DATABASE_URL,

  // Maximum number of clients in the pool (default: 10).
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being closed and removed
  // from the pool (default: 30 s).
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait before timing out when connecting a new client
  // (default: 5 s — pg's own default is 0, i.e. unlimited).
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10
  ),

  // Keep SSL flexible: set DB_SSL=true in environments that require it.
  ssl:
    process.env.DB_SSL === 'true'
      ? { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' }
      : false,
};

// ---------------------------------------------------------------------------
// 4.  Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(POOL_CONFIG);

// ---------------------------------------------------------------------------
// 5.  Pool-level error handler
//
//     pg emits an 'error' event on the Pool whenever a client experiences an
//     unexpected error *while it is idle* (e.g. the server closes the TCP
//     connection).  Without this handler Node.js would throw an unhandled
//     exception and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here — this event fires outside of any request context.
  // The pool will automatically remove the broken client and create a new one
  // the next time a connection is requested.
});

// Useful for diagnosing pool exhaustion in development / staging logs.
pool.on('connect', () => {
  console.info(
    `[db] New client connected. Pool size: ${pool.totalCount} total, ` +
      `${pool.idleCount} idle, ${pool.waitingCount} waiting.`
  );
});

pool.on('remove', () => {
  console.info(
    `[db] Client removed. Pool size: ${pool.totalCount} total, ` +
      `${pool.idleCount} idle.`
  );
});

// ---------------------------------------------------------------------------
// 6.  Health-check function
//
//     Acquires a client, runs a cheap `SELECT 1` round-trip, then releases
//     the client back to the pool.  Returns a structured result object so
//     callers can embed the output directly in a /health endpoint response.
//
//     Signature: healthCheck() → Promise<{ healthy: boolean, detail: object }>
// ---------------------------------------------------------------------------
async function healthCheck() {
  const startedAt = Date.now();
  let client;

  try {
    client = await pool.connect();
    await client.query('SELECT 1');
    const latencyMs = Date.now() - startedAt;

    return {
      healthy: true,
      detail: {
        latencyMs,
        totalClients: pool.totalCount,
        idleClients: pool.idleCount,
        waitingRequests: pool.waitingCount,
      },
    };
  } catch (err) {
    const latencyMs = Date.now() - startedAt;
    console.error('[db] Health check failed:', err.message);

    return {
      healthy: false,
      detail: {
        latencyMs,
        error: err.message,
        totalClients: pool.totalCount,
        idleClients: pool.idleCount,
        waitingRequests: pool.waitingCount,
      },
    };
  } finally {
    // Always release the client, even if the query threw.
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// 7.  Graceful shutdown helper
//
//     Call this during SIGTERM / SIGINT handling so the pool drains cleanly
//     and in-flight queries are not cut off mid-transaction.
// ---------------------------------------------------------------------------
async function shutdown() {
  console.info('[db] Draining connection pool…');
  await pool.end();
  console.info('[db] All database connections closed.');
}

// ---------------------------------------------------------------------------
// 8.  Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** The underlying pg.Pool — use for direct queries: pool.query(…) */
  pool,

  /**
   * Runs a SELECT 1 round-trip and returns pool stats.
   * @returns {Promise<{ healthy: boolean, detail: object }>}
   */
  healthCheck,

  /**
   * Gracefully closes all pool connections.  Call during process shutdown.
   * @returns {Promise<void>}
   */
  shutdown,
};

