/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test at runtime using dotenv and
 * establishes a pg connection pool. Exports the pool and a
 * healthCheck() function for verifying connectivity.
 *
 * Usage:
 *   const { pool, healthCheck } = require('./db');
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op if the variable is already set in the process
//    environment, so this is safe to call unconditionally.
// ---------------------------------------------------------------------------
require('dotenv').config({ path: path.resolve(__dirname, '.env.test') });

const connectionString = process.env.DATABASE_URL;

if (!connectionString) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Ensure .env.test exists and contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 2. Create the connection pool
//    Pool settings below are conservative defaults suitable for most apps.
//    Tune max, idleTimeoutMillis, and connectionTimeoutMillis for your load.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString,

  // Maximum number of clients kept in the pool.
  max: 10,

  // How long (ms) a client may sit idle before being released.
  idleTimeoutMillis: 30_000,

  // How long (ms) to wait for a connection before throwing an error.
  connectionTimeoutMillis: 5_000,

  // Enforce SSL in non-test environments; .env.test targets a local/dev DB.
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true }
    : false,
});

// ---------------------------------------------------------------------------
// 3. Pool-level error handler
//    Catches errors emitted by idle clients (e.g. unexpected disconnections).
//    Without this listener an unhandled 'error' event would crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  console.error('[db] Stack:', err.stack);
  // Do NOT re-throw here — pg emits these asynchronously and the originating
  // call stack is already gone. Let the pool recover on its own.
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// 4. Health-check function
//    Acquires a single client, runs a trivial query, then releases it.
//    Returns a plain object so callers can forward it as a JSON response.
// ---------------------------------------------------------------------------
/**
 * Verifies that the pool can reach the database.
 *
 * @returns {Promise<{
 *   status: 'healthy' | 'unhealthy',
 *   timestamp: string,
 *   responseTimeMs: number,
 *   serverVersion?: string,
 *   error?: string
 * }>}
 */
async function healthCheck() {
  const start = Date.now();
  let client;

  try {
    client = await pool.connect();

    // `version()` returns a single string like
    //   "PostgreSQL 15.3 on x86_64-pc-linux-gnu, compiled by gcc …"
    const result = await client.query('SELECT version(), NOW() AS server_time;');
    const { version, server_time } = result.rows[0];

    return {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      responseTimeMs: Date.now() - start,
      serverVersion: version,
      serverTime: server_time,
    };
  } catch (err) {
    console.error('[db] healthCheck failed:', err.message);

    return {
      status: 'unhealthy',
      timestamp: new Date().toISOString(),
      responseTimeMs: Date.now() - start,
      error: err.message,
    };
  } finally {
    // Always release the client back to the pool, even on error.
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// 5. Graceful shutdown helper
//    Call this during SIGTERM / SIGINT handling to drain the pool cleanly.
// ---------------------------------------------------------------------------
/**
 * Ends all pool clients gracefully.
 * @returns {Promise<void>}
 */
async function closePool() {
  console.log('[db] Closing connection pool…');
  await pool.end();
  console.log('[db] Connection pool closed.');
}

// ---------------------------------------------------------------------------
// 6. Exports
// ---------------------------------------------------------------------------
module.exports = { pool, healthCheck, closePool };

