/**
 * db.js — PostgreSQL connection pool module
 *
 * SECURITY NOTES:
 *  - Credentials are NEVER hardcoded here. DATABASE_URL is read exclusively
 *    from process.env at runtime.
 *  - Loading a .env file (e.g. via `dotenv`) should only happen in the
 *    application entry point (e.g. index.js / server.js), not inside modules.
 *  - In production, inject DATABASE_URL through your platform's secret
 *    manager (e.g. AWS Secrets Manager, Vault, Railway, Render, etc.).
 *  - Never commit .env files containing real credentials to version control.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Validate required environment variable at startup
// ---------------------------------------------------------------------------
const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  throw new Error(
    '[db] Missing required environment variable: DATABASE_URL\n' +
    'Ensure it is set in your environment or loaded via dotenv in your entry point.'
  );
}

// ---------------------------------------------------------------------------
// 2. Build pool configuration from the connection string
//    All values come from the URL; no credentials are embedded here.
// ---------------------------------------------------------------------------
const poolConfig = {
  connectionString: DATABASE_URL,

  // Use SSL in production; skip for local / CI environments that set
  // NODE_ENV=development or NODE_ENV=test explicitly.
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }   // strict certificate validation in prod
      : false,

  // Pool tuning — adjust to match your workload and DB plan limits.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),   // max connections
  min: parseInt(process.env.DB_POOL_MIN ?? '2', 10),    // idle connections kept alive
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT ?? '30000', 10),  // 30 s
  connectionTimeoutMillis: parseInt(process.env.DB_CONN_TIMEOUT ?? '5000', 10), // 5 s
};

// ---------------------------------------------------------------------------
// 3. Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//    Catches errors emitted by idle clients so they don't crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw here — let the pool recover.  If you need alerting,
  // forward `err` to your observability platform (e.g. Sentry, Datadog).
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// 5. Exported query helper
//    Acquires a connection, runs the query, then releases automatically.
// ---------------------------------------------------------------------------

/**
 * Run a parameterised SQL query against the pool.
 *
 * @param {string}  text    - Parameterised SQL string  (e.g. 'SELECT * FROM users WHERE id = $1')
 * @param {Array}   [params] - Bound parameter values    (e.g. [42])
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 * const { rows } = await query('SELECT * FROM users WHERE id = $1', [userId]);
 */
async function query(text, params = []) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log(`[db] Executed query | duration: ${duration}ms | rows: ${result.rowCount}`);
    return result;
  } catch (err) {
    console.error('[db] Query error:', err.message);
    console.error('[db] Failed query text:', text);
    throw err; // Re-throw so callers can handle / respond with HTTP 500, etc.
  }
}

// ---------------------------------------------------------------------------
// 6. Transaction helper
//    Acquires a dedicated client, wraps work in BEGIN/COMMIT/ROLLBACK.
// ---------------------------------------------------------------------------

/**
 * Execute multiple statements inside a single transaction.
 *
 * @param {function(import('pg').PoolClient): Promise<T>} callback
 *   An async function that receives the client and runs queries on it.
 *   Return value is forwarded to the caller.
 * @returns {Promise<T>}
 *
 * @example
 * const result = await withTransaction(async (client) => {
 *   await client.query('INSERT INTO orders ...');
 *   await client.query('UPDATE inventory ...');
 *   return { success: true };
 * });
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('[db] Transaction rolled back due to error:', err.message);
    throw err;
  } finally {
    client.release(); // Always return the client to the pool.
  }
}

// ---------------------------------------------------------------------------
// 7. Health check function
//    Verifies the pool can reach the database. Suitable for /health endpoints.
// ---------------------------------------------------------------------------

/**
 * Perform a lightweight connectivity check against the database.
 *
 * Sends `SELECT 1` and measures round-trip latency.
 * Returns a structured result so callers can surface details in health routes.
 *
 * @returns {Promise<{
 *   healthy: boolean,
 *   latencyMs: number,
 *   timestamp: string,
 *   poolStats: { total: number, idle: number, waiting: number },
 *   error?: string
 * }>}
 *
 * @example
 * app.get('/health/db', async (req, res) => {
 *   const result = await healthCheck();
 *   res.status(result.healthy ? 200 : 503).json(result);
 * });
 */
async function healthCheck() {
  const start = Date.now();

  try {
    await pool.query('SELECT 1');
    const latencyMs = Date.now() - start;

    return {
      healthy: true,
      latencyMs,
      timestamp: new Date().toISOString(),
      poolStats: {
        total:   pool.totalCount,
        idle:    pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    return {
      healthy: false,
      latencyMs: Date.now() - start,
      timestamp: new Date().toISOString(),
      poolStats: {
        total:   pool.totalCount,
        idle:    pool.idleCount,
        waiting: pool.waitingCount,
      },
      error: err.message,
    };
  }
}

// ---------------------------------------------------------------------------
// 8. Graceful shutdown helper
//    Call this during SIGTERM / SIGINT to drain the pool cleanly.
// ---------------------------------------------------------------------------

/**
 * Drain all pool connections and shut down gracefully.
 * Register this in your process signal handlers.
 *
 * @returns {Promise<void>}
 *
 * @example
 * process.on('SIGTERM', async () => {
 *   await closePool();
 *   process.exit(0);
 * });
 */
async function closePool() {
  try {
    await pool.end();
    console.log('[db] Connection pool closed.');
  } catch (err) {
    console.error('[db] Error closing connection pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 9. Exports
// ---------------------------------------------------------------------------
module.exports = {
  query,          // Simple parameterised query
  withTransaction,// Multi-statement transaction wrapper
  healthCheck,    // Connectivity + pool stats check
  closePool,      // Graceful shutdown
  pool,           // Raw pool (for advanced use cases)
};

