/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (via dotenv) and exposes a configured
 * pg.Pool instance, connection-error handling, and a healthCheck() helper.
 *
 * Usage:
 *   const { pool, healthCheck } = require('./db');
 *   const result = await pool.query('SELECT NOW()');
 *   const status = await healthCheck();
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op for keys that are already set in process.env,
//    so this is safe to call in any environment.
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');

const envResult = dotenv.config({
  path: path.resolve(__dirname, '.env.test'),
});

if (envResult.error) {
  // Non-fatal at module load time — the missing-URL guard below will catch it.
  console.warn(
    '[db] Warning: could not parse .env.test —',
    envResult.error.message,
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is present before creating the pool.
//    Failing loudly here prevents cryptic "connect ECONNREFUSED" errors later.
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
      'Make sure .env.test exists and contains a valid DATABASE_URL.',
  );
}

// ---------------------------------------------------------------------------
// 3. Build the Pool
//    All connection options are derived from DATABASE_URL; the extra fields
//    tune pool behaviour for typical web-service workloads.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,

  // Keep up to 10 clients in the pool (default is also 10, made explicit).
  max: 10,

  // Kill idle clients that have been sitting unused for 30 seconds.
  idleTimeoutMillis: 30_000,

  // Fail fast if a new client cannot be checked out within 5 seconds.
  connectionTimeoutMillis: 5_000,

  // Enforce SSL in production; skipped when NODE_ENV is 'test' or 'development'
  // so local dev databases without certificates still work.
  ssl:
    process.env.NODE_ENV === 'production'
      ? { rejectUnauthorized: true }
      : false,
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//    Errors emitted by *idle* clients (e.g. the DB server closed the socket)
//    are caught here. Without this listener the error would be an unhandled
//    'error' event and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw; the pool will automatically replace the broken client.
});

// ---------------------------------------------------------------------------
// 5. Pool lifecycle hooks (optional — useful for debugging connection counts)
// ---------------------------------------------------------------------------
pool.on('connect', () => {
  console.debug(
    `[db] New client connected (pool size: ${pool.totalCount})`,
  );
});

pool.on('remove', () => {
  console.debug(
    `[db] Client removed from pool (pool size: ${pool.totalCount})`,
  );
});

// ---------------------------------------------------------------------------
// 6. healthCheck()
//    Checks out a client, runs a trivial query, and releases the client back
//    to the pool. Returns a resolved/rejected Promise so callers can await it
//    or wire it into an Express /health route.
//
//    Returned shape (on success):
//      { healthy: true, timestamp: <ISO string>, latencyMs: <number> }
//
//    Returned shape (on failure):
//      { healthy: false, error: <message>, latencyMs: <number> }
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  let client;
  try {
    // pool.connect() respects connectionTimeoutMillis set above.
    client = await pool.connect();

    // SELECT 1 is the canonical lightweight connectivity probe.
    const { rows } = await client.query(
      'SELECT 1 AS ok, NOW() AS server_time',
    );

    const latencyMs = Date.now() - start;
    const serverTime = rows[0]?.server_time?.toISOString?.() ?? null;

    console.info(`[db] Health check passed (${latencyMs} ms, server_time=${serverTime})`);

    return {
      healthy: true,
      timestamp: serverTime,
      latencyMs,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;

    console.error(`[db] Health check failed (${latencyMs} ms):`, err.message);

    return {
      healthy: false,
      error: err.message,
      latencyMs,
    };
  } finally {
    // Always release the client, even when an error was thrown, so the pool
    // slot is freed for other callers.
    if (client) {
      client.release();
    }
  }
}

// ---------------------------------------------------------------------------
// 7. gracefulShutdown()
//    Drains all pool clients cleanly. Wire this into SIGTERM / SIGINT so the
//    process does not exit with open sockets.
//
//    Example:
//      process.on('SIGTERM', async () => {
//        await gracefulShutdown();
//        process.exit(0);
//      });
// ---------------------------------------------------------------------------
async function gracefulShutdown() {
  console.info('[db] Draining connection pool…');
  try {
    await pool.end();
    console.info('[db] Pool drained — all clients released.');
  } catch (err) {
    console.error('[db] Error while draining pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 8. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /** The raw pg.Pool instance — use for queries: pool.query(...) */
  pool,

  /**
   * Runs a lightweight SELECT probe and returns
   * { healthy, timestamp, latencyMs } or { healthy: false, error, latencyMs }.
   */
  healthCheck,

  /**
   * Calls pool.end() to drain all connections.
   * Should be awaited during process shutdown.
   */
  gracefulShutdown,
};

